import test from 'node:test';
import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {projectLabelReport,createLabelReportsLoader,LABEL_REPORTS,reportableLabel} from '../src/label-reports.mjs';

// Generated by music-operations-engine tests/label-reports.test.js (WRITE_REPORT_FIXTURE) — the engine contract.
const fixture=JSON.parse(await readFile(new URL('./fixtures/engine-label-reports.json',import.meta.url),'utf8'));
const labelId='label_alpha';
const nowMs=Math.max(...Object.values(fixture).map(r=>Date.parse(r.generatedAt)))+1000;

test('every engine label report validates through its report module projection',()=>{
 assert.deepEqual(Object.keys(fixture).sort(),[...LABEL_REPORTS].sort());
 const r=Object.fromEntries(LABEL_REPORTS.map(name=>[name,projectLabelReport(name,fixture[name],{labelId,nowMs})]));
 assert.equal(r.catalog.state,'live');assert.equal(r.catalog.data.releases[0].tracks[0].isrc,'USABC1234567');assert.equal(r.catalog.data.releases[0].releaseDate,null);
 assert.equal(r.streams.state,'live');assert.equal(r.streams.data.totalStreams,'42');
 assert.equal(r.sales.state,'live');
 const usd=r.sales.data.summary.currencies.find(c=>c.currency==='USD');
 assert.deepEqual([usd.grossMinor,usd.refundMinor,usd.pendingNetMinor],['1000','400','600']);
 assert.deepEqual(r.sales.data.unattributedRefunds,[{currency:'USD',amountMinor:'250'}]);
 assert.equal(r.toolost.state,'live');assert.equal(r.toolost.data.statements[0].royaltiesMinor,'115');assert.equal(r.toolost.data.statements[0].lines[0].units,null);
 assert.equal(r.scenesignal.state,'live');assert.equal(r.scenesignal.data.sessions[0].attendance,'12');
 assert.equal(r.scenesignal.data.sessions[0].engagements,null,'groups below the privacy minimum stay suppressed');
 assert.equal(r.health.state,'live');assert.deepEqual(r.health.data.observations.map(o=>o.sourceId),['dsp','scenesignal']);
 for(const name of ['events','stems','artist']) assert.equal(r[name].state,'awaiting',name);
 assert.equal(r.trackzero.state,'not-applicable');
});

test('awaiting, aged (cached) and mismatched reports are labelled honestly',()=>{
 assert.equal(projectLabelReport('streams',{...fixture.streams,records:[]},{labelId,nowMs}).state,'awaiting');
 assert.equal(projectLabelReport('catalog',{...fixture.catalog,releases:[]},{labelId,nowMs}).state,'awaiting');
 assert.equal(projectLabelReport('streams',fixture.streams,{labelId,nowMs:nowMs+72*3600000}).state,'cached');
 assert.equal(projectLabelReport('health',fixture.health,{labelId,nowMs:nowMs+72*3600000}).state,'cached');
 assert.throws(()=>projectLabelReport('streams',fixture.streams,{labelId:'label_other',nowMs}));
 assert.throws(()=>projectLabelReport('sales',{...fixture.sales,events:[{...fixture.sales.events[0],amountMinor:'-1'}]},{labelId,nowMs}));
 const synthetic={...fixture.streams,records:fixture.streams.records.map(r=>({...r,source:{...r.source,kind:'synthetic'}}))};
 assert.equal(projectLabelReport('streams',synthetic,{labelId,nowMs}).state,'synthetic');
});

test('loader keeps the last valid report as cached after a failed refresh and rejects unsupported label ids',async()=>{
 let fail=false;const calls=[];
 const loader=createLabelReportsLoader({now:()=>nowMs,fetchImpl:async path=>{calls.push(path);
  if(fail) return {ok:false,status:502,json:async()=>({})};
  const name=path.split('/').pop();return {ok:true,status:200,json:async()=>fixture[name]};}});
 const first=await loader.load(labelId);
 assert.equal(first.streams.state,'live');assert.equal(calls.length,10);
 assert.ok(calls.every(p=>p.startsWith('/api/labels/label_alpha/reports/')));
 fail=true;const second=await loader.load(labelId);
 assert.equal(second.streams.state,'cached');assert.equal(second.streams.data.totalStreams,'42');
 const fresh=createLabelReportsLoader({fetchImpl:async()=>({ok:false,status:502,json:async()=>({})})});
 assert.equal((await fresh.load(labelId)).streams.state,'unavailable');
 assert.equal(reportableLabel('alpha'),false);await assert.rejects(loader.load('alpha'));
});
